<script setup lang="ts">
const config=useRuntimeConfig(),cart=useCartStore(); const {data:zones}=await useFetch<any[]>(`${config.public.apiBase}/delivery-zones`); const zone=ref(''); const alias=ref(''),phone=ref(''),address=ref(''),method=ref('Paiement à la livraison'); const result=ref<any>(null),error=ref(''),busy=ref(false); const delivery=computed(()=>zones.value?.find(z=>z.id===zone.value)?.fee||0); const total=computed(()=>cart.subtotal+Number(delivery.value));
async function submit(){error.value='';busy.value=true;try{result.value=await $fetch(`${config.public.apiBase}/orders`,{method:'POST',body:{delivery_zone_id:zone.value,customer_alias:alias.value||null,customer_phone:phone.value,delivery_address:address.value,payment_method:method.value,items:cart.lines.map(l=>({variant_id:l.variant.id,quantity:l.quantity}))}});cart.clear()}catch(e:any){error.value=e?.data?.detail||'Commande non envoyée. Vérifiez les informations et réessayez.'}finally{busy.value=false}}
</script>
<template><div class="mx-auto grid max-w-4xl gap-8 md:grid-cols-2"><section><NuxtLink to="/" class="text-sm text-rose-800">← Continuer mes achats</NuxtLink><h1 class="my-5 text-3xl font-bold">Commande discrète</h1><div v-if="result" class="rounded-2xl bg-emerald-50 p-6"><h2 class="text-xl font-semibold">Merci pour votre commande</h2><p class="mt-2">Référence : <strong>{{ result.order_number }}</strong></p><p class="mt-2">Total : {{ result.total }} FCFA</p></div><form v-else class="space-y-4" @submit.prevent="submit"><input v-model="alias" class="w-full rounded-xl border p-3" placeholder="Pseudonyme (facultatif)"><input v-model="phone" required class="w-full rounded-xl border p-3" placeholder="Téléphone"><select v-model="zone" required class="w-full rounded-xl border p-3"><option value="" disabled>Zone de livraison</option><option v-for="z in zones||[]" :key="z.id" :value="z.id">{{ z.name }} · {{ z.fee }} FCFA</option></select><textarea v-model="address" required class="w-full rounded-xl border p-3" placeholder="Point de repère / adresse" rows="3"/><select v-model="method" class="w-full rounded-xl border p-3"><option>Paiement à la livraison</option><option>Mobile Money</option></select><p v-if="error" class="text-sm text-red-700">{{ error }}</p><button :disabled="busy||!cart.lines.length" class="w-full rounded-xl bg-rose-800 p-3 font-semibold text-white disabled:opacity-50">{{ busy?'Envoi…':'Confirmer la commande' }}</button></form></section><aside class="h-fit rounded-2xl border bg-white p-5"><h2 class="text-xl font-semibold">Récapitulatif</h2><div v-for="line in cart.lines" :key="line.variant.id" class="flex justify-between gap-3 border-b py-3 text-sm"><span>{{ line.productName }} × {{ line.quantity }}</span><span>{{ line.variant.price*line.quantity }} F</span></div><p class="mt-4 flex justify-between">Sous-total <span>{{ cart.subtotal }} F</span></p><p class="mt-2 flex justify-between">Livraison <span>{{ delivery }} F</span></p><p class="mt-3 flex justify-between border-t pt-3 text-lg font-bold">Total <span>{{ total }} FCFA</span></p><p class="mt-5 rounded-xl bg-rose-50 p-3 text-sm text-rose-900">Livraison sous packaging 100% neutre et scellé.</p></aside></div></template>
